Definition rs_cmp_post (sp : word) (spa : Z) (gp tp rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (lo shi E bs fb P tot k ff fp : Z) (iseof : bool) (hw : word) (tmp gap optc ectc fbc : list cell) (j56 j120 : list byte) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists m',
       munch [(Z.shiftr ff 3 + 2147450880 + 4, Z.shiftr ff 3 + 2147450880 + 7)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spa
    /\ rs_frame m' sp spa ff E bs P fb (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) tmp gap
    /\ rw_cells bsegs m' fb fbc /\ rw_cells bsegs m' E (ErrCodeCells (rs_ec iseof))
    /\ as_RFS H ((2, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi
    /\ accessible m' E 24 /\ accessible m' fb 48 /\ AXStatics2 m' /\ AMiscVt48 m'
    /\ (   (iseof = true /\ rs_fake m' ff fp hw optc j56 ectc j120 0 248
            /\ ms' = MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) (wz 1) a1 a2 a3 a4 a5 a6 a7
                         (wz (ff + 96)) (wz tot) (wz E) (wz k) (wz (E + 16)) (wz (Z.shiftr ff 3 + 2147450880)) (wz (fb + 16)) (wz 2147450880)
                         (wz AGENID) (wz tot) t3 t4 t5 t6)
                     F (Z_to_bv 64 RS_EOF) fc None m' (seg_rom bsegs))
        \/ (iseof = false /\ rs_fake m' ff fp hw optc j56 ectc j120 248 248
            /\ exists a0' a1', ms' = rs_ms RS_PARSE rax sp spa gp tp t0 t1 t2 E a0' a1' a2 a3 a4 a5 a6 a7 tot fb ff (wz k) (wz (E + 16)) t3 t4 t5 t6 F fc m')).
