Lemma rs_cmp : forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m0 m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot k : Z) (iseof : bool)
    (hw : word) (tmp gap optc ectc fbc : list cell) (j56 j120 : list byte),
  as_RFS H LF m0 ->
  rs_frame m sp spa ff E bs P fb (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) tmp gap ->
  rs_fake m ff fp hw optc j56 ectc j120 0 248 -> as_RFS H ((2, ff, fp) :: LF) m -> fresh_frame H LF 2 ff fp ->
  rw_cells bsegs m fb fbc -> Z.of_nat (cells_size fbc) = 48 -> aapp fb 48 -> fsobj H LF fb 48 -> accessible m fb 48 ->
  rw_cells bsegs m E (ErrCodeCells (rs_ec iseof)) -> aapp E 24 -> fsobj H LF E 24 -> accessible m E 24 -> E mod 8 = 0 ->
  AXStatics2 m -> AMiscVt48 m ->
  stk bsegs m lo spa -> aceil <= lo -> lo <= spa ->
  0 <= bs < 2^64 -> 0 <= P < 2^64 -> 0 <= tot < 2^64 -> 0 <= k < 2^64 ->
  mem_inv bsegs m -> ACONST m -> stack0 m lo shi ->
  evt bsegs (rs_cmp_post sp spa gp tp rax t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 F fc LF lo shi E bs fb P tot k ff fp iseof hw tmp gap optc ectc fbc j56 j120 m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) (wz (if iseof then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
             (wz (ff + 96)) (wz tot) (wz E) (wz k) (wz (E + 16)) (wz (Z.shiftr ff 3 + 2147450880)) (wz (fb + 16)) (wz 2147450880)
             (wz AGENID) (wz tot) t3 t4 t5 t6)
        F (Z_to_bv 64 RS_CMP) fc None m (seg_rom bsegs)).
